test('invoiceTotals does not mutate input', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 21 }],
  };
  const before = JSON.stringify(invoice);
  invoiceTotals(invoice);
  const after = JSON.stringify(invoice);
  assert.equal(before, after);
});

test('lineDiscount with bulk discount (10+ units)', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 };
  const discount = lineDiscount(line);
  // total: 10000, regular discount: 0, bulk: 10000 * 2.5% = 250
  assert.equal(discount, 250);
});

test('lineDiscount with bulk discount (15 units)', () => {
  const line = { qty: 15, unitPrice: 1000, discountPercent: 0, vatRate: 21 };
  const discount = lineDiscount(line);
  // total: 15000, regular discount: 0, bulk: 15000 * 2.5% = 375
  assert.equal(discount, 375);
});

test('lineDiscount with bulk discount and existing discount', () => {
  const line = { qty: 10, unitPrice: 10000, discountPercent: 10, vatRate: 21 };
  const discount = lineDiscount(line);
  // total: 100000, regular: 10000, remaining: 90000, bulk: 90000 * 2.5% = 2250
  // total discount: 10000 + 2250 = 12250
  assert.equal(discount, 12250);
});

test('lineDiscount without bulk discount (9 units)', () => {
  const line = { qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 21 };
  const discount = lineDiscount(line);
  // total: 9000, no bulk discount
  assert.equal(discount, 0);
});

test('lineDiscount without bulk discount (exactly 9 units)', () => {
  const line = { qty: 9, unitPrice: 5000, discountPercent: 5, vatRate: 21 };
  const discount = lineDiscount(line);
  // total: 45000, regular: 2250, no bulk (qty < 10)
  assert.equal(discount, 2250);
});

test('lineVat with bulk discount', () => {
  const line = { qty: 10, unitPrice: 10000, discountPercent: 0, vatRate: 21 };
  const vat = lineVat(line);
  // total: 100000, discount: 2500, base: 97500, vat: 97500 * 21% = 20475
  assert.equal(vat, 20475);
});

test('lineVat with bulk discount and existing discount', () => {
  const line = { qty: 10, unitPrice: 10000, discountPercent: 10, vatRate: 21 };
  const vat = lineVat(line);
  // total: 100000, regular discount: 10000, remaining: 90000, bulk: 2250
  // base: 100000 - 10000 - 2250 = 87750, vat: 87750 * 21% = 18427.5 → 18428
  assert.equal(vat, 18428);
});

test('invoiceTotals includes bulk discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // total: 10000, discount: 250 (bulk only), vat: (10000 - 250) * 21% = 2037.5 → 2038
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 250);
  assert.equal(totals.vat, 2038);
  assert.equal(totals.total, 11788);
});

test('invoiceTotals with mixed bulk and non-bulk lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
      { qty: 5, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: total 10000, discount 250, vat 2038
  // Line 2: total 5000, discount 0, vat 1050
  assert.equal(totals.subtotal, 15000);
  assert.equal(totals.discount, 250);
  assert.equal(totals.vat, 3088);
});

test('bulk discount with zero regular discount', () => {
  const line = { qty: 10, unitPrice: 5000, discountPercent: 0, vatRate: 0 };
  const discount = lineDiscount(line);
  // total: 50000, regular: 0, bulk: 50000 * 2.5% = 1250
  assert.equal(discount, 1250);
});

test('bulk discount with high regular discount', () => {
  const line = { qty: 10, unitPrice: 10000, discountPercent: 50, vatRate: 21 };
  const discount = lineDiscount(line);
  // total: 100000, regular: 50000, remaining: 50000, bulk: 50000 * 2.5% = 1250
  // total: 50000 + 1250 = 51250
  assert.equal(discount, 51250);
});

test('bulk discount threshold at exactly 10 units', () => {
  const line9 = { qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 21 };
  const line10 = { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 };
  const discount9 = lineDiscount(line9);
  const discount10 = lineDiscount(line10);
  // 9 units: no bulk discount = 0
  // 10 units: bulk discount = 250
  assert.equal(discount9, 0);
  assert.equal(discount10, 250);
});

test('bulk discount with large quantity', () => {
  const line = { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 21 };
  const discount = lineDiscount(line);
  // total: 100000, bulk: 100000 * 2.5% = 2500
  assert.equal(discount, 2500);
});

test('bulk discount rounding precision', () => {
  const line = { qty: 10, unitPrice: 333, discountPercent: 0, vatRate: 21 };
  const discount = lineDiscount(line);
  // total: 3330, bulk: 3330 * 2.5% = 83.25 → 83
  assert.equal(discount, 83);
});

test('invoiceTotals with bulk discount and voucher', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
    voucher: { amount: 100 },
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 10000, discount: 250, vat: 2038, voucher: 100
  // total: 10000 - 250 + 2038 - 100 = 11688
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 250);
  assert.equal(totals.vat, 2038);
  assert.equal(totals.voucher, 100);
  assert.equal(totals.total, 11688);
});

test('multiple lines with bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
      { qty: 20, unitPrice: 500, discountPercent: 0, vatRate: 21 },
      { qty: 5, unitPrice: 2000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: total 10000, discount 250, vat 2038
  // Line 2: total 10000, discount 250, vat 2038
  // Line 3: total 10000, discount 0, vat 2100
  assert.equal(totals.subtotal, 30000);
  assert.equal(totals.discount, 500);
  assert.equal(totals.vat, 6176);
});

test('bulk discount with fractional calculation', () => {
  const line = { qty: 11, unitPrice: 909, discountPercent: 0, vatRate: 9 };
  const discount = lineDiscount(line);
  // total: 11 * 909 = 9999, bulk: 9999 * 2.5% = 249.975 → 250
  assert.equal(discount, 250);
});

test('lineTotal not affected by bulk discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 };
  const total = lineTotal(line);
  // should always be qty * unitPrice, regardless of discount
  assert.equal(total, 10000);
});

test('bulk discount cumulative with line discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 5, vatRate: 0 };
  const discount = lineDiscount(line);
  // total: 10000, regular: 500, remaining: 9500, bulk: 237.5 → 238
  // total: 500 + 238 = 738
  assert.equal(discount, 738);
});

test('bulk discount does not apply below 10 units with high regular discount', () => {
  const line = { qty: 9, unitPrice: 10000, discountPercent: 50, vatRate: 21 };
  const discount = lineDiscount(line);
  // total: 90000, regular: 45000, no bulk (qty < 10)
  assert.equal(discount, 45000);
});

