test('createInvoice applies different tier discounts to different customers', () => {
  const r = createInvoice({
    customerId: 'C-008', // gold (5%)
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const goldDiscount = r.value.lines[0].discountPercent;

  const r2 = createInvoice({
    customerId: 'C-003', // silver (2.5%)
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
