test('addLine applies tier discount to new lines', () => {
  const r = createInvoice({
    customerId: 'C-008', // gold tier (5%)
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 10 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  const r2 = addLine(invoice, { sku: 'DES-HOUR', qty: 1 });
  assert.equal(r2.ok, true);
  // New line should get gold tier discount (5%)
  assert.equal(r2.value.lines[1].discountPercent, 5);
  // Existing line should keep its discount
  assert.equal(r2.value.lines[0].discountPercent, 10);
});

test('addLine respects explicit discountPercent over tier discount', () => {
  const r = createInvoice({
    customerId: 'C-008', // gold tier (5%)
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  const r2 = addLine(invoice, { sku: 'DES-HOUR', qty: 1, discountPercent: 15 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[1].discountPercent, 15);
});

test('invoiceTotals with tier discounts calculates correctly', () => {
  const r = createInvoice({
    customerId: 'C-008', // gold tier (5%)
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  const totals = invoiceTotals(invoice);
  // LOGO-PACK: 120000 cents = €1,200
  // Discount: 120000 * 5% = 6000 cents = €60 (gold tier)
  // Taxable: 114000, VAT: 114000 * 21% = 23940
  // Total: 120000 - 6000 + 23940 = 137940
  assert.equal(totals.subtotal, 120000);
  assert.equal(totals.discount, 6000);
  assert.equal(totals.vat, 23940);
  assert.equal(totals.total, 137940);
});

test('lineVat calculates VAT on discounted line amount', () => {
  const line = { qty: 1, unitPrice: 10000, discountPercent: 10, vatRate: 21 };
  const vat = lineVat(line);
  // lineTotal: 10000, lineDiscount: 1000, taxable: 9000, VAT: 9000 * 21% = 1890
  assert.equal(vat, 1890);
});

test('lineVat handles 0% VAT', () => {
  const line = { qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 };
  const vat = lineVat(line);
  assert.equal(vat, 0);
});

test('lineVat handles 9% VAT', () => {
  const line = { qty: 2, unitPrice: 5000, discountPercent: 0, vatRate: 9 };
  const vat = lineVat(line);
  // lineTotal: 10000, VAT: 10000 * 9% = 900
  assert.equal(vat, 900);
});

test('lineVat rounds to whole cents', () => {
  const line = { qty: 1, unitPrice: 333, discountPercent: 0, vatRate: 21 };
  const vat = lineVat(line);
  // lineTotal: 333, VAT: 333 * 21% = 69.93, rounds to 70
  assert.equal(vat, 70);
});

test('invoiceTotals includes VAT', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  const totals = invoiceTotals(invoice);
  // LOGO-PACK: 120000 cents, no discount, 21% VAT
  // VAT: 120000 * 21% = 25200
  // Total: 120000 + 25200 = 145200
  assert.equal(totals.subtotal, 120000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 25200);
  assert.equal(totals.total, 145200);
});

test('invoiceTotals calculates VAT correctly with mixed VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }, // 21% VAT
      { sku: 'PRINT-A4', qty: 10, discountPercent: 0 },  // 9% VAT (37 cents each = 370 cents)
    ],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  const totals = invoiceTotals(invoice);
  // LOGO-PACK: 120000 cents, VAT: 120000 * 21% = 25200
  // PRINT-A4: 370 cents, VAT: 370 * 9% = 33.3, rounds to 33
  // Total VAT: 25200 + 33 = 25233
  // Total: 120000 + 370 + 25233 = 145603
  assert.equal(totals.subtotal, 120370);
  assert.equal(totals.vat, 25233);
  assert.equal(totals.total, 145603);
});

test('invoiceTotals with discount and VAT', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 10 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  const totals = invoiceTotals(invoice);
  // LOGO-PACK: 120000, discount: 12000 (10%), taxable: 108000, VAT: 108000 * 21% = 22680
  // Total: 120000 - 12000 + 22680 = 130680
  assert.equal(totals.subtotal, 120000);
  assert.equal(totals.discount, 12000);
  assert.equal(totals.vat, 22680);
  assert.equal(totals.total, 130680);
});

test('invoiceTotals clamps total at 0 even with VAT', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'LOGO-PACK', qty: 1, name: 'Logo package', unitPrice: 100, vatRate: 0, discountPercent: 100 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 100, discount: 100, vat: 0, total: max(0, 100 - 100 + 0) = 0
  assert.equal(totals.subtotal, 100);
  assert.equal(totals.discount, 100);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

