  assert.equal(r2.value.voucher.amount, 10000);
});

test('applyVoucher updates invoice totals correctly', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = applyVoucher(draft, { code: 'SUMMER10', amount: 10000 });
  assert.equal(r2.ok, true);
  const invoice = r2.value;

  const totals = invoiceTotals(invoice);
  // Total before voucher: 145200 (120000 + 25200 VAT)
  // Total after voucher: 145200 - 10000 = 135200
