  assert.equal(r.ok, true);
  const invoice = r.value;

  const existing = ['INV-2026-0001', 'INV-2026-0002'];
  const r2 = issueInvoice(invoice, existing);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2026-0003');
});

