test('invoiceTotals includes discount and VAT', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 10 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 120000);
  assert.equal(totals.discount, 12000); // 10% of 120000
  // Taxable: 108000, VAT: 108000 * 21% = 22680
  assert.equal(totals.vat, 22680);
  assert.equal(totals.total, 130680); // 120000 - 12000 + 22680
});

test('invoiceTotals calculates discount correctly with multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 10 },
      { sku: 'DES-HOUR', qty: 2, discountPercent: 5 },
    ],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 120000 + 17000); // 137000
  assert.equal(totals.discount, 12000 + 850); // 12850
  // LOGO-PACK: taxable 108000, VAT 22680; DES-HOUR: taxable 16150, VAT 3391.5≈3392; total VAT: 26072
  assert.equal(totals.vat, 26072);
  assert.equal(totals.total, 150222); // 137000 - 12850 + 26072
});

test('invoiceTotals clamps total at 0 if discount exceeds subtotal', () => {
